#include "ksSerialTransmitTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
#include <utility>
int main(){using T=ks::SerialTransmitTask;using S=T::Stage;using W=T::Write;unsigned cases=0;auto verify=[&](unsigned producer,unsigned consumer,unsigned wait,unsigned input){T t;unsigned reads=0,used=0;std::vector<std::pair<W,unsigned>>writes;auto clock=[&](W w){auto at=w==W::Enable?0xffff8au:t.dataAddress();return at>=0xfffd10?1u:3u;};while(t.stage()!=S::Complete){auto cost=t.nextClocks(clock);if(t.advanceBefore(cost-1,[](T::Read){return 0;},[](W,uint16_t){},clock))throw std::runtime_error("early");used+=t.advanceBefore(cost,[&](T::Read r){if(r==T::Read::Input)return input;if(r==T::Read::Producer)return producer;unsigned next=(producer+1)&255;return reads++<wait?next:consumer==next?(consumer^1):consumer;},[&](W w,uint16_t value){if(w==W::Data&&reads!=0)throw std::runtime_error("data must publish before space wait");writes.emplace_back(w,value);},clock);}std::vector<std::pair<W,unsigned>>expected{{W::Data,input},{W::Producer,(producer+1)&255},{W::Enable,0xf0}};if(writes!=expected||reads!=wait+1||t.dataAddress()!=((0xffed70+producer)&0xffffff)||used!=215+clock(W::Data)+clock(W::Enable)+21*wait)throw std::runtime_error("TX ordering/data/clock/fullqueue");++cases;};for(unsigned producer=0;producer<256;++producer)for(unsigned consumer=0;consumer<256;++consumer)verify(producer,consumer,0,producer^consumer);for(unsigned wait=0;wait<256;++wait)for(unsigned data=0;data<256;++data)verify(255,0,wait,data);for(unsigned producer=0;producer<65536;++producer)verify(producer,1,0,(producer*149)&255);std::cout<<"PASS: "<<cases<<" pure serial-transmit properties\n";}
